1002	function refresh(opts) {
1003	  // Ahead of the empty-board bail: the controls are preferences in their own
1004	  // right, and a change to them is worth keeping whether or not there is
1005	  // anything on the grid to re-plan yet.
1006	  schedulePrefsSave();
1007	  if (state.matched.length === 0) return;
1008	  const animate = !(opts && opts.animate === false);
1009	  const filter = currentFilter();
1010	  const summ = summarize(state.matched, filter, state.totalFavourites);
1011	
1012	  // Time the reschedule computation itself (buildSchedule) for the header pill.
1013	  const t0 = performance.now();
1014	  const planOpts = gatherPlanOptions();
1015	  const schedule = buildSchedule(state.matched, planOpts);
1016	  recordResched(performance.now() - t0);
1017	  state.schedule = schedule;
1018	  state.scheduledSlugs = new Set(schedule.scheduled.map((s) => s.slug));
1019	  // The exact performance the plan chose for each scheduled show, so the grid
1020	  // can ring that one mark (the "selected plan" the user sees on the lanes).
1021	  state.selectedSlot = new Map(schedule.scheduled.map((s) => [s.slug, slotKey(s)]));
1022	
1023	  // Which controls are, on their own, making a catchable show un-placeable —
1024	  // drives the "prevents N shows" labels, the lane marks, and the schedule
1025	  // overlay badges.
1026	  state.diag = placementDiagnostics(state.matched, {
1027	    dateStart: planOpts.dateStart,
1028	    dateEnd: planOpts.dateEnd,
1029	    dayStartMin: state.dayStartMin,
1030	    dayEndMin: effectiveDayEnd(),
1031	    dayEndCeil: DAY_END_CEIL,
1032	    mealBreaks: state.mealBreaks,
1033	    venueCoords: state.venueCoords,
1034	  });
1035	  updateBlockLabels(state.diag);
1036	
1037	  const bySlug = new Map(summ.shows.map((s) => [s.slug, s]));
1038	  applyVerdicts(bySlug, filter);
1039	  renderCounts(schedule.counts.scheduledShows);
1040	  updatePlanWindowLabel();
1041	
1042	  renderPlanSummary(schedule);
1043	  renderSchedule(schedule, animate);
1044	  const hasShows = schedule.scheduled.length > 0;
1045	  $("downloadCsvBtn").disabled = !hasShows;
