1049	/**
1050	 * The right-hand verdict a lane shows when it isn't in the plan. Distinct kinds
1051	 * so the reason a show didn't make it is legible at a glance:
1052	 *   - scheduled  : this show made the plan            ✓ Scheduled!
1053	 *   - early      : catchable, but only before day-start  ☀ Too early
1054	 *   - late       : catchable, but only after day-end     🌙 Too late
1055	 *   - lunch      : every performance lands on your lunch break  🍽 Lunch conflict
1056	 *   - dinner     : …or on your dinner break                     🍽 Dinner conflict
1057	 *   - meal       : both meal breaks, together, shut it out      🍽 Meal conflict
1058	 *   - cantfit    : catchable in the window, but a clash / cap left no room
1059	 *   - sold       : every performance in the window (or the whole run) is sold out
1060	 *   - baddates   : has bookable performances, but all fall outside your dates
1061	 */
1062	function laneStatus(show, filter, sets) {
1063	  if (sets.scheduled) return { kind: "scheduled" };
1064	  const perfs = show.performances || [];
1065	  const inWindow = perfs.filter((p) => p.date >= filter.dateStart && p.date <= filter.dateEnd);
1066	  const availInWindow = inWindow.filter((p) => p.available);
1067	
1068	  if (availInWindow.length > 0) {
1069	    // placementDiagnostics lists a show under every control that would rescue it
1070	    // on its own, so name the culprit when there's exactly one kind of culprit —
1071	    // a break the user can move reads far better than a flat "can't fit".
1072	    const early = sets.earlySet.has(show.slug);
1073	    const late = sets.lateSet.has(show.slug);
1074	    const lunch = sets.lunchSet.has(show.slug);
1075	    const dinner = sets.dinnerSet.has(show.slug);
1076	    if (!lunch && !dinner) {
1077	      if (early && !late) return { kind: "early" };
1078	      if (late && !early) return { kind: "late" };
1079	    } else if (!early && !late) {
1080	      if (lunch && !dinner) return { kind: "lunch" };
1081	      if (dinner && !lunch) return { kind: "dinner" };
1082	      return { kind: "meal" };
1083	    }
1084	    return { kind: "cantfit" };
1085	  }
1086	
1087	  // Nothing catchable in the window. Sold out (in-window, or the whole run)
1088	  // takes priority over "bad dates" — a different window won't help a sold-out
1089	  // run, whereas bad dates are exactly what the date scrubber fixes.
1090	  const runSold = perfs.length > 0 && perfs.every((p) => p.soldOut);
1091	  const windowSold = inWindow.length > 0 && inWindow.every((p) => p.soldOut);
1092	  if (runSold || windowSold) return { kind: "sold" };
1093	  return { kind: "baddates" };
1094	}
1095	
1096	/* The verdicts caused by a control the user owns — a meal break, the day's
1097	 * start or end. Each is drawn as a button that carries you to the setting
1098	 * responsible (see wireConflictJumps), because the useful next move on
1099	 * "Lunch conflict" is to look at your lunch. */
1100	const CONFLICT_KINDS = {
1101	  early: { label: "Too early", control: "ctlDayStart" },
1102	  late: { label: "Too late", control: "ctlDayEnd" },
1103	  lunch: { label: "Lunch conflict", control: "mealLunchStart" },
1104	  dinner: { label: "Dinner conflict", control: "mealDinnerStart" },
1105	  meal: { label: "Meal conflict", control: "mealLunchStart" },
1106	};
1107	
1108	/** The status pill HTML for a lane verdict (see laneStatus for the kinds). */
1109	function statusPillHTML(status) {
1110	  // No native title attributes — those are the browser's ugly tooltip; the short
1111	  // pill label carries the verdict on its own, and the conflict pills below
1112	  // open a real explanation on hover (see conflictTipHTML).
1113	  const conflict = CONFLICT_KINDS[status.kind];
1114	  if (conflict) {
1115	    return (
1116	      `<button type="button" class="st-blocked st-conflict" data-conflict="${status.kind}">` +
1117	      `<span class="st-warn" aria-hidden="true">▲</span>${conflict.label}</button>`
1118	    );
1119	  }
1120	  switch (status.kind) {
1121	    case "scheduled":
1122	      return `<span class="st-plan">&check;&nbsp;Scheduled!</span>`;
1123	    case "cantfit":
1124	      return `<span class="st-cant">Can't fit</span>`;
1125	    case "sold":
1126	      return `<span class="st-sold">Sold out</span>`;
1127	    case "baddates":
1128	    default:
1129	      return `<span class="st-dates">📅 No dates</span>`;
1130	  }
1131	}
1132	
1133	/**
