import { chromium } from "playwright";

const BASE = "http://localhost:8123";
const SHOT = (n) => `/tmp/claude-0/-home-user-EdFringeNow/f2dc9757-507e-522a-8720-e35ecdadcf85/scratchpad/${n}.png`;

const browser = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium/chrome-linux/chrome" });
const page = await browser.newPage({ viewport: { width: 1500, height: 1000 } });

// Seed favourites + prefs before the app boots.
await page.addInitScript(() => {
  localStorage.setItem(
    "edfringe.plan.favourites.v1",
    JSON.stringify({
      v: 1,
      slugs: ["paddy-young-will-sir-be-laughing-alone", "be-good-with-paulette"],
      filename: null,
      savedAt: Date.now(),
    })
  );
  localStorage.setItem(
    "edfringe.plan.prefs.v1",
    JSON.stringify({
      v: 1,
      d0: 1,
      d1: 31,
      dayStartMin: 600, // 10:00
      dayEndMin: 1230, // 20:30 — cuts the 20:00 (ends 21:00) and 22:15 perfs
      mode: "walk",
      meals: [
        { id: "lunch", enabled: true, startMin: 810, endMin: 870 }, // 13:30–14:30 — covers 13:25 + 13:50 perfs
        { id: "dinner", enabled: false, startMin: 1080, endMin: 1140 },
      ],
      arrival: { enabled: false, endMin: 0 },
      departure: { enabled: false, startMin: 1620 },
      forced: [],
      pacing: { gap: "0", max: "8", min: "1" },
    })
  );
});

await page.goto(`${BASE}/plan/`, { waitUntil: "networkidle" });
await page.waitForSelector(".lane", { timeout: 20000 });
await page.waitForTimeout(1000);

// Report every lane's verdict.
const verdicts = await page.$$eval(".lane", (lanes) =>
  lanes.map((l) => ({
    title: l.querySelector(".lane-title")?.textContent?.trim(),
    status: l.querySelector(".lane-status")?.textContent?.trim(),
    kinds: l.querySelector(".st-conflict")?.dataset?.kinds ?? null,
    conflict: l.querySelector(".st-conflict")?.dataset?.conflict ?? null,
  }))
);
console.log(JSON.stringify(verdicts, null, 2));

const paddy = page.locator(".lane", { hasText: "Paddy Young" });
await paddy.screenshot({ path: SHOT("combo-lane") });

// Hover the pill → tip should appear.
const pill = paddy.locator(".st-conflict");
await pill.hover();
await page.waitForTimeout(400);
const tipText = await page.$eval("#calTip", (t) => (t.hidden ? "(hidden)" : t.textContent.trim()));
console.log("TIP:", tipText);
await page.screenshot({ path: SHOT("combo-tip"), clip: await paddy.boundingBox().then((b) => ({
  x: Math.max(0, b.x - 20), y: Math.max(0, b.y - 190), width: Math.min(1480, b.width + 40), height: b.height + 210,
})) });

// Click → should scroll to the plan controls and flash both lunch + day end.
await pill.click();
await page.waitForTimeout(700);
const flashed = await page.$$eval(".ctl--flash", (els) => els.map((e) => e.textContent.trim().slice(0, 40)));
console.log("FLASHED:", JSON.stringify(flashed));
await page.screenshot({ path: SHOT("combo-jump") });

await browser.close();
console.log("done");

